// utils/export/pdf.ts
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";

export interface PDFColumn<T = any> {
  header: string;
  accessor: keyof T | ((row: T) => any);
  width?: number;
  align?: "left" | "center" | "right";
  formatter?: (value: any, row: T) => string;
}

export interface PDFExportOptions {
  filename?: string;
  title?: string;
  subtitle?: string;
  orientation?: "portrait" | "landscape";
  pageSize?: "a4" | "letter" | "legal";
  showHeader?: boolean;
  showFooter?: boolean;
  showPageNumbers?: boolean;
  startY?: number;
  tableStyles?: {
    headStyles?: any;
    bodyStyles?: any;
    alternateRowStyles?: any;
    columnStyles?: any;
  };
  customRender?: (doc: jsPDF) => void;
}

export interface PDFConfig {
  schoolName?: string;
  schoolAddress?: string;
  schoolPhone?: string;
  schoolEmail?: string;
  logoBase64?: string;
}
function resolveValue<T>(
  row: T,
  accessor: keyof T | ((row: T) => unknown),
): unknown {
  if (typeof accessor === "function") {
    return accessor(row);
  }

  return (row as any)[accessor];
}

// Default school configuration
const DEFAULT_SCHOOL_CONFIG: PDFConfig = {
  schoolName:
    process.env.NEXT_PUBLIC_SCHOOL_NAME || "KIDDIEWISE SCHOOL COMPLEX",
  schoolAddress:
    process.env.NEXT_PUBLIC_SCHOOL_ADDRESS ||
    "Oyarifa Road (Off Container Junction), Accra, Ghana",
  schoolPhone: process.env.NEXT_PUBLIC_SCHOOL_PHONE || "+233(0) 54 179 0780",
  schoolEmail:
    process.env.NEXT_PUBLIC_SCHOOL_EMAIL || "kiddiewise2012@gmail.com",
  logoBase64:
    "",
};
async function addLogoToPDF(doc: jsPDF): Promise<void> {
  return new Promise((resolve) => {
    try {
      if (DEFAULT_SCHOOL_CONFIG.logoBase64) {
        // Add logo at position (x: 20, y: 15, width: 30, height: 30)
        doc.addImage(DEFAULT_SCHOOL_CONFIG.logoBase64, "JPEG", 20, 15, 30, 30);
      }
      resolve();
    } catch (error) {
      console.log("Logo not available:", error);
      resolve();
    }
  });
}

/**
 * Generic PDF exporter for any data type
 */
export async function exportToPDF<T = any>(
  data: T[],
  columns: PDFColumn<T>[],
  options: PDFExportOptions = {},
  config: PDFConfig = DEFAULT_SCHOOL_CONFIG,
): Promise<void> {
  const doc = new jsPDF({
    orientation: options.orientation || "portrait",
    unit: "mm",
    format: options.pageSize || "a4",
  });

  // Add school header
  if (options.showHeader !== false) {
    addSchoolHeader(doc, config);
  }

  let startY = options.startY || (options.showHeader !== false ? 50 : 20);

  // Add title and subtitle
  if (options.title) {
    doc.setFontSize(16);
    doc.setTextColor(0, 0, 0);
    doc.setFont("helvetica", "bold");
    doc.text(options.title, 105, startY, { align: "center" });
    startY += 8;
  }

  if (options.subtitle) {
    doc.setFontSize(10);
    doc.setTextColor(100, 100, 100);
    doc.setFont("helvetica", "normal");
    doc.text(options.subtitle, 105, startY, { align: "center" });
    startY += 10;
  }

  // Generate the data rows
  const tableData = data.map((row) => {
    return columns.map((col) => {
      let value = resolveValue(row, col.accessor);

      if (col.formatter) {
        value = col.formatter(value, row);
      }

      return String(value ?? "—");
    });
  });

  const headers = columns.map((col) => col.header);

  // Build column styles
  const columnStyles: any = {};
  columns.forEach((col, index) => {
    if (col.width) {
      columnStyles[index] = { cellWidth: col.width };
    }
    if (col.align) {
      columnStyles[index] = { ...columnStyles[index], halign: col.align };
    }
  });

  // Apply table styles
  const headStyles = {
    fillColor: [30, 58, 95],
    textColor: 255,
    fontSize: 10,
    fontStyle: "bold",
    halign: "center",
    ...options.tableStyles?.headStyles,
  };

  const bodyStyles = {
    fontSize: 9,
    cellPadding: 4,
    ...options.tableStyles?.bodyStyles,
  };

  const alternateRowStyles = {
    fillColor: [245, 245, 245],
    ...options.tableStyles?.alternateRowStyles,
  };

  // Add the table
  autoTable(doc, {
    startY,
    head: [headers],
    body: tableData,
    headStyles,
    bodyStyles,
    alternateRowStyles,
    columnStyles,
    margin: { top: 20, left: 15, right: 15 },
    styles: {
      overflow: "linebreak",
      cellWidth: "wrap",
    },
    pageBreak: "auto",
  });

  // Add footer
  if (options.showFooter !== false) {
    const finalY = (doc as any).lastAutoTable?.finalY || startY;
    addFooter(doc, finalY + 10, options.showPageNumbers !== false);
  }

  // Custom render hook
  if (options.customRender) {
    options.customRender(doc);
  }

  // Download the PDF
  const filename =
    options.filename || `export-${new Date().toISOString().split("T")[0]}`;
  doc.save(`${filename}.pdf`);
}

/**
 * Add school header to PDF
 */
function addSchoolHeader(doc: jsPDF, config: PDFConfig): void {
  // Add logo if provided
  if (config.logoBase64) {
    try {
      doc.addImage(config.logoBase64, "JPEG", 20, 15, 30, 30);
    } catch (error) {
      console.error("Failed to add logo:", error);
    }
  }

  // School name
  doc.setFontSize(18);
  doc.setTextColor(30, 58, 95);
  doc.setFont("helvetica", "bold");
  doc.text(config.schoolName || "SCHOOL NAME", 105, 25, { align: "center" });

  // School address
  doc.setFontSize(9);
  doc.setTextColor(100, 100, 100);
  doc.setFont("helvetica", "normal");
  if (config.schoolAddress) {
    doc.text(config.schoolAddress, 105, 33, { align: "center" });
  }

  // Contact info
  let contactLine = "";
  if (config.schoolPhone) contactLine += `Tel: ${config.schoolPhone}`;
  if (config.schoolEmail) contactLine += ` | Email: ${config.schoolEmail}`;
  if (contactLine) {
    doc.text(contactLine, 105, 39, { align: "center" });
  }

  // Divider line
  doc.setDrawColor(200, 200, 200);
  doc.line(20, 45, 190, 45);
}

/**
 * Add footer to PDF
 */
function addFooter(doc: jsPDF, startY: number, showPageNumbers: boolean): void {
  const pageCount = (doc as any).internal.getNumberOfPages();
  const pageHeight = doc.internal.pageSize.height;

  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);

    // Add divider line
    doc.setDrawColor(200, 200, 200);
    doc.line(20, pageHeight - 15, 190, pageHeight - 15);

    // Add generation date
    doc.setFontSize(8);
    doc.setTextColor(150, 150, 150);
    doc.setFont("helvetica", "normal");
    doc.text(
      `Generated on: ${new Date().toLocaleDateString()}`,
      20,
      pageHeight - 8,
    );

    // Add page numbers if requested
    if (showPageNumbers) {
      doc.text(`Page ${i} of ${pageCount}`, 190, pageHeight - 8, {
        align: "right",
      });
    }
  }

  // Go back to first page
  doc.setPage(1);
}
